<template>
  <div class="overview-page"><AppHeader /><main class="overview-main">
    <div class="overview-topline"><span><span class="signal-dot" />NEXUS / WORKSPACE</span><time>{{ today }}</time></div>
    <section class="overview-hero">
      <div class="hero-grid" aria-hidden="true" /><div class="hero-copy"><span class="hero-kicker">KNOWLEDGE × CONNECTION</span><h1>智能的下一次跃迁，<br /><em>从互联开始。</em></h1><p>发现值得复用的 Skill，连接实用的 MCP。<br />在这里，把工具、知识和协作放在一起。</p><div class="hero-actions"><RouterLink to="/skills" class="btn btn-primary"><Blocks :size="16" />探索 Skill<ArrowUpRight :size="15" /></RouterLink><RouterLink to="/mcp-servers" class="btn btn-secondary"><Plug :size="16" />连接 MCP</RouterLink></div></div>
      <div class="network-art" aria-hidden="true"><div class="orbit orbit-one" /><div class="orbit orbit-two" /><div class="orbit orbit-three" /><div class="core-node"><Network :size="40" /><strong>NEXUS</strong></div><div class="satellite satellite-a"><Blocks :size="22" /><span>SKILL</span></div><div class="satellite satellite-b"><Plug :size="22" /><span>MCP</span></div><div class="satellite satellite-c"><Handshake :size="20" /></div><span class="art-caption">IDEAS BECOME POSSIBILITIES</span></div>
    </section>
    <section class="overview-stats" aria-label="资源统计"><RouterLink to="/skills"><Blocks :size="19" /><span>已收录 Skill<small>可复用的方法与能力</small></span><strong>{{ skillTotal ?? '—' }}</strong><ArrowUpRight :size="14" /></RouterLink><RouterLink to="/mcp-servers"><Plug :size="19" /><span>已收录 MCP<small>连接外部工具与数据</small></span><strong>{{ mcpTotal ?? '—' }}</strong><ArrowUpRight :size="14" /></RouterLink><RouterLink to="/help-requests"><CircleHelp :size="19" /><span>从一个问题开始<small>发布需求，找到同行者</small></span><ArrowUpRight :size="17" /></RouterLink></section>
    <section class="discovery-section"><header class="section-heading"><div><span class="section-index">01 / DISCOVER</span><h2>发现新的可能</h2></div><div class="discovery-tabs"><button :class="{active: selectedKind === 'skill'}" :aria-pressed="selectedKind === 'skill'" @click="selectedKind = 'skill'">Skill</button><button :class="{active: selectedKind === 'mcp'}" :aria-pressed="selectedKind === 'mcp'" @click="selectedKind = 'mcp'">MCP</button></div><RouterLink :to="selectedKind === 'skill' ? '/skills' : '/mcp-servers'">浏览全部<ArrowUpRight :size="14" /></RouterLink></header><StatePanel v-if="loading" tone="loading" title="正在探索资源" /><StatePanel v-else-if="error" tone="error" title="资源暂时无法加载" :description="error"><button class="btn btn-secondary" @click="load">重新加载</button></StatePanel><div v-else-if="visibleResources.length" class="resource-grid"><ResourceCard v-for="resource in visibleResources" :key="resource.id" :resource="resource" compact @open="openResource" /></div><StatePanel v-else title="等待第一个好工具" description="收录一个值得推荐的资源，让更多人发现它。"><RouterLink :to="selectedKind === 'skill' ? '/skills' : '/mcp-servers'" class="btn btn-secondary">开始收录<ArrowUpRight :size="15" /></RouterLink></StatePanel></section>
