<script setup lang="ts">
import { computed, onBeforeUnmount, ref } from 'vue'
import { RouterLink, useRouter } from 'vue-router'
import { ArrowUpRight, Blocks, CircleHelp, Handshake, MessagesSquare, Network, Plug } from '@lucide/vue'
import AppHeader from '@/components/AppHeader.vue'
import StatePanel from '@/components/StatePanel.vue'
import ResourceCard from '@/features/resources/ResourceCard.vue'
import { listResources, errorMessage, type Resource } from '@/features/resources/api'
import '@/features/resources/resources.css'
const router = useRouter()
const today = new Date().toLocaleDateString('zh-CN', {year:'numeric',month:'2-digit',day:'2-digit'})
const skillTotal = ref<number>(); const mcpTotal = ref<number>()
const skills = ref<Resource[]>([]); const mcps = ref<Resource[]>([])
const loading = ref(false); const error = ref(''); const selectedKind = ref<'skill'|'mcp'>('skill')
const visibleResources = computed(() => (selectedKind.value === 'skill' ? skills.value : mcps.value).slice(0,3))
const communityEntries = [
  { to:'/forum', title:'参与讨论', description:'分享经验，交流想法，留下有价值的发现。', icon:MessagesSquare },
  { to:'/help-requests', title:'发布求助', description:'把需求说清楚，让合适的人与你相遇。', icon:CircleHelp },
  { to:'/collaborations', title:'推进协作', description:'跟进任务、记录决定，把成果交付到位。', icon:Handshake },
]
let controller: AbortController | undefined
async function load() { controller?.abort(); const request = new AbortController(); controller=request; loading.value=true; error.value=''; try { const [s,m] = await Promise.all([listResources({kind:'skill',q:'',scope:'all',page:0},request.signal),listResources({kind:'mcp',q:'',scope:'all',page:0},request.signal)]); if(request.signal.aborted)return; skills.value=s.items; mcps.value=m.items; skillTotal.value=s.total; mcpTotal.value=m.total } catch(e) {if(!request.signal.aborted)error.value=errorMessage(e)} finally{if(!request.signal.aborted)loading.value=false} }
function openResource(resource:Resource) { void router.push({path:resource.kind==='skill'?'/skills':'/mcp-servers',query:{resource:resource.id}}) }
onBeforeUnmount(()=>controller?.abort()); void load()
</script>
